import{_ as l,C as a,o as s,c as h,a2 as o,j as d,a as t,E as n}from"./chunks/framework.CtQGab4e.js";const j=JSON.parse('{"title":"Het 3D-paneel","description":"","frontmatter":{},"headers":[],"relativePath":"plattegrond/3d-paneel.md","filePath":"plattegrond/3d-paneel.md"}'),g={name:"plattegrond/3d-paneel.md"};function p(m,e,b,k,u,c){const r=a("Icon"),i=a("Media");return s(),h("div",null,[e[5]||(e[5]=o('<h1 id="het-3d-paneel" tabindex="-1">Het 3D-paneel <a class="header-anchor" href="#het-3d-paneel" aria-label="Permalink to &quot;Het 3D-paneel&quot;">​</a></h1><p>In het 3D-paneel maak je van je plattegrond een 3D-model, met de m² per constructie. Daarna controleer en corrigeer je de constructies en exporteer je de uitkomst.</p><p>Er gaat alleen een tekening naar de 3D-server, zonder titel, adres of naam. De server bewaart niets.</p><h2 id="aanzetten" tabindex="-1">Aanzetten <a class="header-anchor" href="#aanzetten" aria-label="Permalink to &quot;Aanzetten&quot;">​</a></h2><p>Je hebt een persoonlijke <strong>3D-sleutel</strong> nodig. Vul die in bij <a href="./../tool/instellingen.html#_3d">Instellingen</a>.</p><h2 id="openen" tabindex="-1">Openen <a class="header-anchor" href="#openen" aria-label="Permalink to &quot;Openen&quot;">​</a></h2>',6)),d("p",null,[e[0]||(e[0]=t("Tik op ",-1)),n(r,{name:"model3d"}),e[1]||(e[1]=t()),e[2]||(e[2]=d("strong",null,"3D",-1)),e[3]||(e[3]=t(" of kies het in het menu ",-1)),n(r,{name:"menu"}),e[4]||(e[4]=t(". Het paneel komt naast je tekening; nog een keer tikken sluit het.",-1))]),e[6]||(e[6]=o('<p>Het paneel kan op drie manieren in beeld staan (knoppen rechtsboven in het paneel):</p><table tabindex="0"><thead><tr><th>Stand</th><th>Hoe</th><th>Wanneer</th></tr></thead><tbody><tr><td><strong>Naast de tekening</strong></td><td>standaard</td><td>Tekenen en het 3D-model tegelijk zien. Sleep het grijze streepje om de verdeling te kiezen.</td></tr><tr><td><strong>3D volledig</strong></td><td>⤢</td><td>Het paneel vult het scherm.</td></tr><tr><td><strong>Eigen venster</strong></td><td>↗</td><td>Het paneel in een los venster, bijvoorbeeld op een tweede scherm. Niet op de iPad.</td></tr></tbody></table><p>Is het paneel smal, zoals op een iPad in staande stand, dan staan de constructies onder het 3D-model.</p><h2 id="genereren" tabindex="-1">Genereren <a class="header-anchor" href="#genereren" aria-label="Permalink to &quot;Genereren&quot;">​</a></h2><ol><li>Teken de plattegrond af: hoogtes en referentiepunten in <a href="./gebouw.html">Gebouweigenschappen</a>, installaties aan de ruimtes, daken bij de gevels.</li><li>Open het 3D-paneel en tik op <strong>Genereer</strong>. Na een paar seconden staat het model in beeld, met ernaast (of eronder) de constructies.</li></ol><p>Het model en de berekening blijven bij de notitie bewaard, met je correcties.</p><p>Teken je daarna verder, dan zie je <em>De tekening is gewijzigd na het genereren</em>: tik opnieuw op <strong>Genereer</strong> voor een nieuw model.</p><div class="warning custom-block"><p class="custom-block-title">Correcties vervallen bij opnieuw genereren</p><p>Heb je constructies aangepast (zie <a href="./constructies.html">Constructies en correcties</a>), dan vraagt Genereer eerst of je doorgaat. Een nieuw model komt met een nieuwe berekening: je correcties vervallen.</p></div><h2 id="het-model-bekijken" tabindex="-1">Het model bekijken <a class="header-anchor" href="#het-model-bekijken" aria-label="Permalink to &quot;Het model bekijken&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Muis</th><th>Pen of vinger</th></tr></thead><tbody><tr><td><strong>Draaien</strong></td><td>slepen</td><td>slepen</td></tr><tr><td><strong>Zoomen</strong></td><td>scrollwiel, naar het punt onder de muis</td><td>via een constructie (hieronder)</td></tr><tr><td><strong>Constructie kiezen</strong></td><td>klik op een vlak</td><td>tik op een vlak</td></tr><tr><td><strong>Plat beeld</strong></td><td><kbd>Spatie</kbd></td><td>dubbeltik op het vlak</td></tr><tr><td><strong>Niets gekozen</strong></td><td><kbd>Esc</kbd> of klik naast het model</td><td>tik naast het model</td></tr></tbody></table><p><strong>Plat beeld</strong> draait het model recht voor de gekozen constructie en zoomt erop in; nog een keer terug.</p><p>De kleuren en arceringen staan in de legenda linksboven. <strong>Doorzichtig</strong> = buiten de berekening, bijvoorbeeld een kelderblok of een niet-berekende garage.</p><h2 id="het-log" tabindex="-1">Het log <a class="header-anchor" href="#het-log" aria-label="Permalink to &quot;Het log&quot;">​</a></h2><p>Onder het model staat het log: wat de 3D-server heeft gedaan, en elke melding over je tekening. Wat die meldingen betekenen: <a href="./export-3d.html#meldingen">Meldingen</a>.</p><h2 id="als-er-iets-misgaat" tabindex="-1">Als er iets misgaat <a class="header-anchor" href="#als-er-iets-misgaat" aria-label="Permalink to &quot;Als er iets misgaat&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Melding</th><th>Wat te doen</th></tr></thead><tbody><tr><td><em>De 3D-server is niet bereikbaar</em> / <em>reageert niet</em></td><td>Controleer je internet en tik op <strong>Opnieuw verbinden</strong>. Blijft het zo, probeer het later.</td></tr><tr><td><em>Controleer je 3D-sleutel in de instellingen</em></td><td>De sleutel klopt niet. Kijk hem na bij <a href="./../tool/instellingen.html">Instellingen</a>.</td></tr><tr><td><em>Probeer het zo opnieuw</em></td><td>De 3D-server heeft het druk. Wacht de tijd die erbij staat.</td></tr><tr><td><em>Er is een nieuwe versie van de teken-tool</em></td><td>Vernieuw de pagina.</td></tr><tr><td><em>Er ging iets mis op de 3D-server</em></td><td>Geef het <strong>verzoek-id</strong> uit het log door, samen met het 3D-bestand van <a href="./export-3d.html#het-3d-bestand">Exporteren voor 3D</a>.</td></tr></tbody></table>',16)),n(i,{todo:"Afbeelding: het 3D-paneel naast de tekening, met labels bij Genereer, het model, de legenda, het log en de constructies."})])}const f=l(g,[["render",p]]);export{j as __pageData,f as default};
